style.css:
@-moz-document domain("monkeytype.com") {
/* Set the background image */
    body {
        background: url("https://i.imgur.com/KGNDz1B.png") no-repeat center center fixed;
        background-size: cover;
        background-color: #000; /* Fallback color if image fails */
    }

    /* Add a dark overlay for better text readability */
    body::before {
        content: "";
        position: fixed;
        top: 0; left: 0; right: 0; bottom: 0;
        background: rgba(0, 0, 0, 0.5); /* Black with 50% opacity */
        z-index: 0;
    }

    /* Make sure content appears above the overlay */
    .main, .top, .bottom, .navbar, .words, .customScrollbar {
        position: relative;
        z-index: 1;
    }

    /* Style the words section for better visibility */
    .words {
        color: #ffffff;
    }
}
